import 'dart:io';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter/rendering.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:nothingness/models/operating_mode.dart';
import 'package:nothingness/models/screen_config.dart';
import 'package:nothingness/models/theme_id.dart';
import 'package:nothingness/services/playback_controller.dart';
import 'package:nothingness/services/settings_service.dart';
import 'package:nothingness/theme/themes.dart';
import 'package:nothingness/widgets/void_settings_sheet.dart';
import 'package:provider/provider.dart';
import 'package:shared_preferences/shared_preferences.dart';


Widget _wrap(Widget child) {
  return MaterialApp(
    theme: buildAppTheme(id: ThemeId.void_, brightness: Brightness.dark),
    home: child,
  );
}

Future<void> _capturePng({
  required WidgetTester tester,
  required Finder boundaryFinder,
  required String outPath,
}) async {
  final boundary = tester.renderObject<RenderRepaintBoundary>(boundaryFinder);
  final image = await boundary.toImage(pixelRatio: 1.0);
  final byteData = await image.toByteData(format: ui.ImageByteFormat.png);
  if (byteData == null) return;

  await File(outPath).writeAsBytes(byteData.buffer.asUint8List());
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  setUp(() async {
    // Avoid persistence leaking across tests.
    SharedPreferences.setMockInitialValues(<String, Object>{});

    final s = SettingsService();
    s.operatingModeNotifier.value = OperatingMode.own;
    s.screenConfigNotifier.value = const CassetteScreenConfig();
  });

  testWidgets('Cassette screen shows cassette variant controls directly under screen row',
      (tester) async {
    await tester.binding.setSurfaceSize(const Size(800, 900));
    addTearDown(() => tester.binding.setSurfaceSize(null));

    final boundaryKey = const ValueKey('void-settings-capture');

    await tester.pumpWidget(
      _wrap(
        RepaintBoundary(
          key: boundaryKey,
          child: Provider<PlaybackController?>.value(
            value: null,
            child: const VoidSettingsSheet(),
          ),
        ),
      ),
    );

    // Let async effects (e.g. version label probe) settle so layout stabilises.
    await tester.pumpAndSettle();

    await _capturePng(
      tester: tester,
      boundaryFinder: find.byKey(boundaryKey),
      outPath: '.tmp/void_settings_cassette.png',
    );

    // Placement sanity: both rows are reachable and variant row is present.
    expect(find.byKey(const ValueKey('void-settings-screen')), findsOneWidget);
    expect(
      find.byKey(const ValueKey('void-settings-cassette-variant')),
      findsOneWidget,
    );
  });
}

